package com.adaptivelearning.goalproject.domain;
import com.adaptivelearning.shared.exception.BusinessException;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class StateMachineTest {@Test void goalAllowsDocumentedTransitions(){assertThatCode(()->GoalStatus.DRAFT.requireCanTransitionTo(GoalStatus.ACTIVE)).doesNotThrowAnyException();assertThatThrownBy(()->GoalStatus.COMPLETED.requireCanTransitionTo(GoalStatus.PAUSED)).isInstanceOf(BusinessException.class);}@Test void projectCompletedOnlyArchives(){assertThatCode(()->ProjectStatus.COMPLETED.requireCanTransitionTo(ProjectStatus.ARCHIVED)).doesNotThrowAnyException();assertThatThrownBy(()->ProjectStatus.COMPLETED.requireCanTransitionTo(ProjectStatus.ACTIVE)).isInstanceOf(BusinessException.class);}}
